package com.procurement.vendorquotation.mapper;import com.procurement.vendorquotation.dto.response.*;import com.procurement.vendorquotation.entity.*;import org.springframework.stereotype.Component;@Component public class VendorQuotationMapper{public VendorQuotationResponse toResponse(VendorQuotation e){return new VendorQuotationResponse(e.getId(),e.getQuotationNumber(),e.getRfq().getId(),e.getRfq().getRfqNumber(),e.getVendor().getId(),e.getVendor().getVendorCode(),e.getVendor().getVendorName(),e.getSubmissionDate(),e.getValidUntil(),e.getCurrency(),e.getSubtotal(),e.getDiscountAmount(),e.getTaxAmount(),e.getShippingCharges(),e.getOtherCharges(),e.getGrandTotal(),e.getPaymentTerms(),e.getDeliveryDays(),e.getDeliveryLocation(),e.getWarrantyMonths(),e.getRemarks(),e.getStatus(),e.getCreatedBy(),e.getUpdatedBy(),e.getCreatedAt(),e.getUpdatedAt());}public VendorQuotationLineResponse line(VendorQuotationLine e){return new VendorQuotationLineResponse(e.getId(),e.getVendorQuotation().getId(),e.getRfqLine().getId(),e.getProduct().getId(),e.getProduct().getProductName(),e.getQuantity(),e.getUnitPrice(),e.getDiscountPercentage(),e.getTaxPercentage(),e.getLineAmount(),e.getRemarks());}public QuotationAttachmentResponse attachment(QuotationAttachment e){return new QuotationAttachmentResponse(e.getId(),e.getVendorQuotation().getId(),e.getFileName(),e.getFilePath(),e.getFileType(),e.getUploadedAt());}}
